INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (400, 1, '기본 복제 방식', 'Redis 복제는 기본으로 **동기·비동기** 중 어느 쪽일까요?', '낮은 지연과 높은 성능을 택했어요.', NULL, NULL, '[]', 'choice', '["동기 복제이며 모든 replica 가 처리해야 응답한다", "과반수 replica 가 처리해야 응답하는 합의 방식", "비동기 복제이며 replica 가 처리한 양을 주기적으로 알린다", "쓰기마다 디스크에 먼저 적고 응답하는 방식"]', 2, 'Redis 문서는 복제가 기본으로 비동기이며 replica 가 처리한 데이터 양을 마스터에 비동기로 확인(acknowledge)한다고 설명합니다. 낮은 지연과 높은 성능 때문입니다.', NULL, NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 2, 'WAIT 의 한계', '클라이언트가 **WAIT** 명령을 쓰면 무엇이 보장될까요?', '강한 일관성은 아니에요.', NULL, NULL, '[]', 'choice', '["장애 조치 때도 확인된 쓰기는 절대 사라지지 않는다", "지정한 수의 replica 확인을 보장하나 강한 일관성은 아님", "모든 replica 의 디스크 저장까지 보장해 준다", "Redis 를 CP 시스템으로 바꿔 준다"]', 1, 'Redis 문서는 WAIT 가 지정한 수의 확인된 사본이 있음을 보장할 뿐 강한 일관성의 CP 시스템으로 만들지는 못하며, 장애 조치에서 확인된 쓰기가 사라질 수 있다고 설명합니다. 다만 손실 확률을 크게 줄입니다.', NULL, NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 3, 'replica 읽기 전용', 'Redis 2.6 이후 replica 는 **기본으로** 쓰기를 어떻게 처리할까요?', 'replica-read-only 예요.', NULL, NULL, '[]', 'choice', '["읽기 전용이라 쓰기 명령을 거부한다", "쓰기를 받아 마스터로 전달해 준다", "쓰기를 받아 로컬에만 적용한다", "쓰기를 받고 마스터와 동기화를 끊는다"]', 0, 'Redis 문서는 2.6 부터 replica 가 읽기 전용 모드를 기본으로 지원하며(replica-read-only), 쓰기 명령을 거부해 실수로 쓰는 것을 막는다고 설명합니다. 쓰기 가능한 replica 는 불일치 위험으로 권장되지 않습니다.', NULL, NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 4, 'replica 의 만료 처리', 'replica 는 **키 만료** 를 어떻게 처리할까요?', '마스터가 DEL 을 보내요.', NULL, NULL, '[]', 'choice', '["replica 가 자기 시계로 직접 만료시켜 지운다", "마스터와 replica 의 시계를 동기화해 함께 지운다", "만료를 무시하고 키를 영구히 보관한다", "스스로 지우지 않고 마스터가 만료·축출하며 보내는 DEL 을 기다린다"]', 3, 'Redis 문서는 replica 가 키를 스스로 만료시키지 않고 마스터가 만료(또는 LRU 축출)할 때 만들어 보내는 DEL 명령을 기다린다고 설명합니다. 시계 동기화에 의존하지 않기 위해서입니다.', NULL, NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 5, '부분 재동기화', '연결이 끊겼다 다시 이어진 replica 는 **PSYNC** 로 무엇을 보낼까요?', '이전 이력과 처리한 위치예요.', NULL, NULL, '[]', 'choice', '["마지막으로 읽은 키 이름들의 목록", "자신의 전체 데이터셋에 대한 해시", "이전 마스터의 복제 ID 와 처리한 오프셋", "마스터의 비밀번호와 포트 번호"]', 2, 'Redis 문서는 replica 가 PSYNC 로 이전 마스터의 복제 ID 와 처리한 오프셋을 보내, 마스터가 백로그가 충분하면 놓친 증분만 보낼 수 있게 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 6, '전체 재동기화', '부분 재동기화가 **불가능** 하면 마스터는 무엇을 할까요?', '스냅샷이 필요해요.', NULL, NULL, '[]', 'choice', '["replica 를 복제 대상에서 영구히 제외해 둔다", "RDB 를 만들어 보내고 이후 명령을 이어 보낸다", "백업 파일을 사람이 옮기도록 알림만 보낸다", "AOF 전체를 처음부터 다시 써서 준다"]', 1, 'Redis 문서는 전체 동기화에서 마스터가 백그라운드 저장으로 RDB 를 만들며 새 쓰기 명령을 버퍼링하고, RDB 를 전송해 replica 가 로드한 뒤 버퍼된 명령을 보낸다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 7, 'min-replicas-to-write', '**min-replicas-to-write** 는 무엇을 할까요?', '쓰기 허용 조건이에요.', NULL, NULL, '[]', 'choice', '["지정한 수 이상의 replica 가 최대 지연 이내일 때만 쓰기를 받는다", "지정한 수의 replica 에 쓰기가 반영되어야 응답한다", "replica 가 지정한 수보다 적으면 자동으로 새로 만든다", "지정한 수 이상의 replica 에 읽기를 분산한다"]', 0, 'Redis 문서는 마스터가 지연이 min-replicas-max-lag 초 이내인 replica 가 min-replicas-to-write 개 이상일 때만 쓰기를 받고 아니면 오류로 거부한다고 설명합니다. 데이터 손실 구간을 제한할 뿐 일관성을 보장하지는 않습니다.', NULL, NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 8, '영속성 끈 마스터의 위험', '복제 구성에서 마스터의 **영속성을 끄고 자동 재시작** 을 두면 어떤 일이 생길 수 있을까요?', '빈 데이터셋으로 되살아나요.', NULL, NULL, '[]', 'choice', '["replica 가 마스터를 자동으로 교체해서 문제가 없다", "마스터가 replica 에서 데이터를 되가져와 복구한다", "자동 재시작이 항상 영속성을 켜 주므로 안전하다", "빈 데이터로 시작한 마스터를 replica 가 복제해 데이터가 지워진다"]', 3, 'Redis 문서는 영속성이 꺼진 마스터가 재시작하며 빈 데이터셋으로 시작하면 replica 들이 그것을 복제해 자기 사본을 파괴한다고 경고합니다. 영속성을 켜거나 자동 재시작을 끄라고 권합니다.', NULL, NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 9, 'replica 의 maxmemory', 'replica 는 **maxmemory** 를 기본으로 어떻게 다룰까요?', '축출은 마스터가 해요.', NULL, NULL, '[]', 'choice', '["자기 메모리가 차면 스스로 키를 축출한다", "메모리가 차면 마스터와 복제를 끊는다", "무시하고 마스터가 보내는 DEL 로 축출이 반영된다", "마스터보다 항상 적은 메모리만 쓴다"]', 2, 'Redis 문서는 replica 가 기본으로 maxmemory 를 무시하고(replica-ignore-maxmemory) 축출은 마스터가 DEL 을 보내 처리한다고 설명합니다. 그래서 replica 가 maxmemory 보다 더 쓸 수 있으니 모니터링해야 합니다.', NULL, NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 10, 'replica 지정 지시어', 'redis.conf 에서 **마스터를 지정** 해 replica 로 만드는 지시어입니다. 빈칸을 채우세요.', '"replica of" 를 붙인 이름이에요.', NULL, NULL, '[]', 'fill', '["replicaof", "slaveto", "masterof", "syncfrom"]', NULL, '문서는 replica 설정 파일에 replicaof 192.168.1.1 6379 한 줄을 넣거나 REPLICAOF 명령을 쓰면 된다고 설명합니다.', '[0]', '{0} 192.168.1.1 6379', NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 11, '디스크 없는 복제', 'RDB 를 디스크를 거치지 않고 네트워크로 바로 보내는 **디스크리스 복제** 설정의 이름입니다. 빈칸을 채우세요.', '"repl-…-sync" 형태예요.', NULL, NULL, '[]', 'fill', '["diskless", "disk", "async", "fast"]', NULL, '문서는 디스크리스 복제를 repl-diskless-sync 설정으로 켠다고 설명합니다. 느린 디스크에서 마스터의 부담을 줄이며 2.8.18 부터 지원합니다.', '[0]', 'repl-{0}-sync yes', NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]'),
  (400, 12, '전체 동기화 과정', '마스터와 replica 의 전체 동기화 과정 순서입니다. 순서에 맞게 놓아 보세요.', '저장 → 전송 → 로드 → 버퍼 전송이에요.', NULL, NULL, '[]', 'order', '["마스터가 백그라운드 저장으로 RDB 를 만들며 새 쓰기를 버퍼링한다", "마스터가 RDB 파일을 replica 에 전송한다", "replica 가 RDB 를 디스크에 저장하고 메모리에 로드한다", "마스터가 버퍼링한 명령을 replica 에 보낸다"]', NULL, 'Redis 복제 문서가 설명한 전체 동기화 순서 그대로입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "Redis 복제", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/replication/"}]');
